// Use telescoping methods rather than default arguments to try and minimize
// the amount of bytecode generated at the callsite.
//
// Because fastparse inlines aggressively, it is very easy for a user to
// generate huge methods, so anything we can do to reduce the size of the
// generated code helps avoid bytecode size blowup

val consumeWhitespace = whitespace match{
  case None => reify{(c: Parse[Any]) => true}
  case Some(ws) =>
    if (ws.tree.tpe =:= typeOf[fasterparser.NoWhitespace.noWhitespaceImplicit.type]){
      reify{(c: Parse[Any]) => true}
    }else{
      reify{(c: Parse[Any]) => ws.splice(c); c.isSuccess}
    }
}

def consumeWhitespace(extraCut: Expr[Boolean])(x: Expr[ParsingRun[V]]) =
  if whitespace.asTerm.tpe =:= TypeRepr.of[fastparse.NoWhitespace.noWhitespaceImplicit.type]
  then x
  else '{
    Util.consumeWhitespace($whitespace, ctx)
    if (!ctx.isSuccess && ($extraCut || ctx.cut)) ctx.asInstanceOf[ParsingRun[Nothing]]
    else { $x }
  }

